import os
import base64

docs_dir = "../insa/docs/rust-core"
os.makedirs(docs_dir, exist_ok=True)

docs_b64 = {
    "01-unsafe-and-trust.md": "",
    "02-zero-allocation-hotpaths.md": "",
    "03-layout-and-cache-alignment.md": "",
    "04-typestate-and-monomorphization.md": "",
    "05-miri-and-ub.md": "",
    "06-error-handling-and-panics.md": ""
}

for name, b64_content in docs_b64.items():
    content = base64.b64decode(b64_content).decode("utf-8")
    path = os.path.join(docs_dir, name)
    with open(path, "w") as f:
        f.write(content.strip() + "\n")
